const CONCURRENCY = 6;

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    const queue = PRECACHE.slice();
    async function worker() {
      while (queue.length) {
        const url = queue.shift();
        const req = new Request(url, { cache: 'reload' });
        let res;
        for (let attempt = 0; attempt < 3; attempt++) {
          try { res = await fetch(req); if (res.ok) break; } catch (e) { res = null; }
        }
        if (!res || !res.ok) throw new Error('precache failed: ' + url + ' ' + (res && res.status));
        await cache.put(url, res);
      }
    }
    await Promise.all(Array.from({ length: CONCURRENCY }, worker));
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) {
      if (key.startsWith('dpdpreview-') && key !== CACHE) await caches.delete(key);
    }
    await self.clients.claim();
  })());
});

async function rangeResponse(request, response) {
  const m = /bytes=(\d*)-(\d*)/.exec(request.headers.get('range') || '');
  if (!m) return response;
  const buf = await response.arrayBuffer();
  const size = buf.byteLength;
  let start = m[1] === '' ? size - Number(m[2]) : Number(m[1]);
  let end = m[1] !== '' && m[2] !== '' ? Number(m[2]) : size - 1;
  start = Math.max(0, start); end = Math.min(size - 1, end);
  const headers = new Headers(response.headers);
  headers.set('Content-Range', 'bytes ' + start + '-' + end + '/' + size);
  headers.set('Content-Length', String(end - start + 1));
  return new Response(buf.slice(start, end + 1), { status: 206, statusText: 'Partial Content', headers });
}

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    let hit = await cache.match(req, { ignoreVary: true });
    if (!hit && req.mode === 'navigate') {
      hit = (await cache.match('./')) || (await cache.match('index.html'));
    }
    if (hit) return req.headers.has('range') ? rangeResponse(req, hit) : hit;
    try {
      const res = await fetch(req);
      if (res.ok && res.status === 200 && !req.headers.has('range')) cache.put(req, res.clone());
      return res;
    } catch (e) {
      if (req.mode === 'navigate') {
        const fallback = await caches.match('index.html');
        if (fallback) return fallback;
      }
      throw e;
    }
  })());
});
